mapper.update:
UPDATE attendance_record SET clock_out_time = #{time}, is_early = #{early}
WHERE user_id = #{userId} AND attendance_date = #{date}
  AND clock_out_time IS NULL AND clock_in_time <= #{time}

mapper.select:
SELECT  FROM attendance_record a
INNER JOIN sys_user u ON u.id = a.user_id
WHERE a.attendance_date BETWEEN #{startDate} AND #{endDate}
AND a.user_id = #{userId}

    AND (LOCATE(#{keyword}, u.user_name) > 0 OR LOCATE(#{keyword}, u.real_name) > 0)

AND u.department_id = #{departmentId}
ORDER BY a.attendance_date DESC, a.id DESC
